CREATE TABLE whatsapp_accounts (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, phone_number_id VARCHAR(64) NOT NULL, waba_id VARCHAR(64) NOT NULL, display_phone VARCHAR(40) NULL, verified_name VARCHAR(200) NULL, quality_rating VARCHAR(20) NULL, token_ciphertext TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending', last_error TEXT NULL, last_tested_at DATETIME(6) NULL, source VARCHAR(20) NOT NULL DEFAULT 'manual', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_accounts_user_uq (user_id), UNIQUE KEY whatsapp_accounts_phone_uq (phone_number_id), UNIQUE KEY whatsapp_accounts_owner_uq (id,user_id), CONSTRAINT whatsapp_accounts_status_ck CHECK (status IN ('pending','connected','error')), CONSTRAINT whatsapp_accounts_source_ck CHECK (source IN ('manual','embedded_signup')), CONSTRAINT whatsapp_accounts_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci